/**
 * A time-ordered UUID version 7 (RFC 9562), like `Guid.CreateVersion7()`: 48-bit Unix milliseconds, then random bits.
 * Ids are generated by the application, never by the database (see docs/domain-model.md).
 */
export function uuidV7(now: Date): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  const millis = now.getTime();
  for (let i = 0; i < 6; i++) {
    bytes[i] = Math.floor(millis / 2 ** (8 * (5 - i))) & 0xff;
  }

  bytes[6] = (bytes[6]! & 0x0f) | 0x70; // version 7
  bytes[8] = (bytes[8]! & 0x3f) | 0x80; // RFC 9562 variant
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/**
 * `Guid.TryParse` for the formats used in URLs: 32 digits (N), hyphenated (D), and D wrapped in braces (B) or
 * parentheses (P). Returns the canonical lower-case D form, or null. Surrounding white space is ignored, as in .NET.
 */
export function parseGuid(value: string): string | null {
  const text = value.trim();
  const match =
    /^([0-9a-f]{8})-?([0-9a-f]{4})-?([0-9a-f]{4})-?([0-9a-f]{4})-?([0-9a-f]{12})$/i.exec(text) ??
    /^\{([0-9a-f]{8})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{12})\}$/i.exec(text) ??
    /^\(([0-9a-f]{8})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{12})\)$/i.exec(text);
  if (!match) return null;

  const hyphenated = text.includes('-');
  const bare = !/[{(]/.test(text);
  if (bare && hyphenated && text.length !== 36) return null; // N has no hyphens, D has all four
  return match.slice(1, 6).join('-').toLowerCase();
}
